package vn.gk.logistics.payments;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import vn.gk.logistics.dispatch.RoutingService;
import java.util.*;
import java.util.function.Supplier;

@RestController
public class PaymentController {
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final RoutingService routing;
 public PaymentController(JdbcTemplate jdbc,ObjectMapper json,RoutingService routing){this.jdbc=jdbc;this.json=json;this.routing=routing;}
 private void conflict(String s){throw new ResponseStatusException(HttpStatus.CONFLICT,s);}
 private Map<?,?> user(HttpServletRequest req,String role){var u=(Map<?,?>)req.getAttribute("user");if(u==null||!role.equals(u.get("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tài khoản không có quyền thực hiện");return u;}
 private String string(Map<String,Object> b,String key,int min,int max){String s=Objects.toString(b.get(key),"").strip();if(s.length()<min||s.length()>max)throw new IllegalArgumentException("Kiểm tra "+key+" ("+min+"–"+max+" ký tự)");return s;}
 private String choice(Map<String,Object>b,String key,String... allowed){String s=string(b,key,1,30);if(!Set.of(allowed).contains(s))throw new IllegalArgumentException("Lựa chọn không hợp lệ: "+key);return s;}
 private String encode(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("Không lưu được phiếu thu tiền");}}
 private Map<String,Object> decode(String v){try{return json.readValue(v,new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> once(String kind,Map<String,Object>b,long uid,Supplier<Map<String,Object>> fn){UUID id;try{id=UUID.fromString(Objects.toString(b.get("requestId"),""));}catch(Exception e){throw new IllegalArgumentException("Thiếu mã yêu cầu hợp lệ");}jdbc.execute("SELECT pg_advisory_xact_lock(7462014)");var rows=jdbc.queryForList("SELECT kind,body::text,result::text,created_by FROM finance_requests WHERE id=?",id);if(!rows.isEmpty()){var r=rows.get(0);if(((Number)r.get("created_by")).longValue()!=uid)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!kind.equals(r.get("kind"))||!decode((String)r.get("body")).equals(decode(encode(b))))conflict("Mã yêu cầu đã dùng với nội dung khác");return decode((String)r.get("result"));}var out=fn.get();jdbc.update("INSERT INTO finance_requests(id,kind,body,result,created_by) VALUES(?,?,?::jsonb,?::jsonb,?)",id,kind,encode(b),encode(out),uid);return out;}
 private Map<String,Object> stop(int id,int did){var s=jdbc.queryForMap("SELECT s.*,t.status AS trip_status,t.driver_id FROM trip_stops s JOIN trips t ON t.id=s.trip_id WHERE s.id=? FOR UPDATE OF s",id);if(((Number)s.get("driver_id")).intValue()!=did)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Điểm không thuộc chuyến của bạn");if(!"in_progress".equals(s.get("trip_status"))||!Set.of("pending","en_route").contains(s.get("state"))||"warehouse".equals(s.get("kind")))conflict("Chỉ thu cước tại điểm lấy/giao đang xử lý");int next=jdbc.queryForObject("SELECT id FROM trip_stops WHERE trip_id=? AND state IN ('pending','en_route') ORDER BY seq LIMIT 1",Integer.class,s.get("trip_id"));if(next!=id)conflict("Hãy xử lý điểm đang đi tới trước");return s;}
 @PostMapping("/api/driver/stops/{id}/payer") @Transactional public Map<String,Object> payer(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req,"driver");routing.changed();return once("payer:"+id,b,((Number)u.get("id")).longValue(),()->{var s=stop(id,((Number)u.get("driver_id")).intValue());if(!"pickup".equals(s.get("kind")))conflict("Chỉ đổi người trả cước lúc lấy hàng");var o=jdbc.queryForMap("SELECT * FROM orders WHERE id=? FOR UPDATE",s.get("order_id"));if(jdbc.queryForObject("SELECT count(*) FROM payment_collections WHERE order_id=?",Integer.class,o.get("id"))>0)conflict("Đã thu cước, không đổi người thanh toán");String payer=choice(b,"payer","sender","recipient");jdbc.update("UPDATE orders SET payment_payer=? WHERE id=?",payer,o.get("id"));jdbc.update("INSERT INTO customer_tracking_events(order_id,type,reason) VALUES(?,'payment_payer_updated',?)",o.get("id"),payer.equals("sender")?"Người gửi thanh toán":"Người nhận thanh toán");return Map.of("payer",payer);});}
 @PostMapping("/api/driver/stops/{id}/collect") @Transactional public Map<String,Object> collect(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req,"driver");routing.changed();return once("collect:"+id,b,((Number)u.get("id")).longValue(),()->{int did=((Number)u.get("driver_id")).intValue();var s=stop(id,did);var o=jdbc.queryForMap("SELECT * FROM orders WHERE id=? FOR UPDATE",s.get("order_id"));if(jdbc.queryForObject("SELECT count(*) FROM payment_collections WHERE order_id=?",Integer.class,o.get("id"))>0)conflict("Đơn đã thu cước, không thu lần nữa");String payer=(String)o.get("payment_payer");if("external".equals(b.get("method"))&&"pickup".equals(s.get("kind"))){payer="sender";jdbc.update("UPDATE orders SET payment_payer=? WHERE id=?",payer,o.get("id"));}if(!(payer.equals("sender")&&s.get("kind").equals("pickup")||payer.equals("recipient")&&s.get("kind").equals("delivery")))conflict("Thu tiền đúng người trả cước và đúng điểm lấy/giao");if(o.get("shipping_fee_vnd")==null||((Number)o.get("shipping_fee_vnd")).longValue()<=0)conflict("Chưa có cước hợp lệ. Nhờ điều phối cập nhật trước khi thu");String method=choice(b,"method","cash","transfer","external"),holder=choice(b,"receivedBy","driver","company"),ref=string(b,"reference",method.equals("transfer")?3:0,120);if(method.equals("cash")&&!holder.equals("driver"))throw new IllegalArgumentException("Tiền mặt tài xế nhận phải ghi đang giữ tại tài xế");long amount=((Number)o.get("shipping_fee_vnd")).longValue();Long cid=jdbc.queryForObject("INSERT INTO payment_collections(order_id,stop_id,driver_id,payer,amount,method,received_by,reference,created_by) VALUES(?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,o.get("id"),id,did,payer,amount,method,holder,ref,u.get("id"));jdbc.update("UPDATE orders SET shipping_price_status='confirmed' WHERE id=?",o.get("id"));jdbc.update("INSERT INTO customer_tracking_events(order_id,type,reason) VALUES(?,'payment_collected',?)",o.get("id"),"Đã thu cước "+amount+" đ · "+(payer.equals("sender")?"Người gửi":"Người nhận")+" · "+(method.equals("cash")?"Tiền mặt":method.equals("transfer")?"Chuyển khoản":"Tài xế xác nhận"));return Map.of("id",cid,"amount",amount,"paid",true);});}
 @PostMapping("/api/driver/stops/{id}/unpaid") @Transactional public Map<String,Object> unpaid(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req,"driver");routing.changed();return once("unpaid:"+id,b,((Number)u.get("id")).longValue(),()->{var s=stop(id,((Number)u.get("driver_id")).intValue());if(!Set.of("pickup","delivery").contains(s.get("kind")))conflict("Điểm này không thu cước");var o=jdbc.queryForMap("SELECT * FROM orders WHERE id=? FOR UPDATE",s.get("order_id"));if(jdbc.queryForObject("SELECT count(*) FROM payment_collections WHERE order_id=?",Integer.class,o.get("id"))>0)conflict("Đơn đã thanh toán; không thể ghi chưa thanh toán");if("pickup".equals(s.get("kind")))jdbc.update("UPDATE orders SET payment_payer='recipient' WHERE id=?",o.get("id"));int inserted=jdbc.update("INSERT INTO payment_decisions(stop_id,order_id,driver_id,created_by) VALUES(?,?,?,?) ON CONFLICT(stop_id) DO NOTHING",id,o.get("id"),u.get("driver_id"),u.get("id"));if(inserted>0)jdbc.update("INSERT INTO customer_tracking_events(order_id,type,reason) VALUES(?,'payment_unpaid',?)",o.get("id"),"pickup".equals(s.get("kind"))?"Chưa thanh toán · Người nhận trả cước khi giao":"Chưa thanh toán cước · Chờ đối soát");return Map.of("paid",false,"acknowledged",true);});}
 private List<Map<String,Object>> collections(Integer did){return jdbc.queryForList("SELECT c.*,o.code,o.warehouse_id,o.stage,o.is_demo,h.status AS handover_status,h.id AS handover_id,r.id AS refund_id,r.paid_by AS refund_paid_by,t.status AS trip_status FROM payment_collections c JOIN orders o ON o.id=c.order_id JOIN trip_stops s ON s.id=c.stop_id JOIN trips t ON t.id=s.trip_id LEFT JOIN cash_handover_items hi ON hi.collection_id=c.id LEFT JOIN cash_handovers h ON h.id=hi.handover_id LEFT JOIN payment_refunds r ON r.collection_id=c.id"+(did==null?"":" WHERE c.driver_id=?")+" ORDER BY c.id DESC LIMIT 200",did==null?new Object[]{}:new Object[]{did});}
 @GetMapping("/api/driver/cash") public Map<String,Object> own(HttpServletRequest req){var u=user(req,"driver");int did=((Number)u.get("driver_id")).intValue();return Map.of("collections",collections(did),"handovers",jdbc.queryForList("SELECT * FROM cash_handovers WHERE driver_id=? ORDER BY id DESC LIMIT 50",did),"balances",jdbc.queryForMap("SELECT coalesce(sum(c.amount),0) AS holding FROM payment_collections c LEFT JOIN cash_handover_items hi ON hi.collection_id=c.id LEFT JOIN cash_handovers h ON h.id=hi.handover_id LEFT JOIN payment_refunds r ON r.collection_id=c.id WHERE c.driver_id=? AND c.received_by='driver' AND c.method<>'external' AND coalesce(h.status,'')<>'approved' AND (r.id IS NULL OR r.paid_by<>'driver')",did));}
 @PostMapping("/api/driver/cash/handovers") @Transactional public Map<String,Object> handover(@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req,"driver");return once("handover",b,((Number)u.get("id")).longValue(),()->{int did=((Number)u.get("driver_id")).intValue();if(!(b.get("collectionIds") instanceof List<?> ids)||ids.isEmpty()||ids.size()>100)throw new IllegalArgumentException("Chọn từ 1 đến 100 khoản thu để nộp");var chosen=new ArrayList<Map<String,Object>>();var seen=new HashSet<Long>();Integer warehouse=null;long total=0;for(var raw:ids){long cid;try{cid=new java.math.BigDecimal(raw.toString()).longValueExact();}catch(Exception e){throw new IllegalArgumentException("Mã khoản thu không hợp lệ");}if(!seen.add(cid))throw new IllegalArgumentException("Không chọn trùng khoản thu");var c=jdbc.queryForMap("SELECT c.*,o.warehouse_id,t.status AS trip_status FROM payment_collections c JOIN orders o ON o.id=c.order_id JOIN trip_stops s ON s.id=c.stop_id JOIN trips t ON t.id=s.trip_id WHERE c.id=? FOR UPDATE OF c",cid);if(((Number)c.get("driver_id")).intValue()!=did||!"driver".equals(c.get("received_by"))||"external".equals(c.get("method")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Chỉ nộp khoản tiền bạn đang giữ");if(!"completed".equals(c.get("trip_status")))conflict("Cần kết thúc chuyến và xác nhận về kho trước khi nộp tiền");if(jdbc.queryForObject("SELECT count(*) FROM cash_handover_items WHERE collection_id=?",Integer.class,cid)>0||jdbc.queryForObject("SELECT count(*) FROM payment_refunds WHERE collection_id=? AND paid_by='driver'",Integer.class,cid)>0)conflict("Khoản thu đã nộp, đang chờ duyệt hoặc đã hoàn từ tài xế");int wh=((Number)c.get("warehouse_id")).intValue();if(warehouse!=null&&warehouse!=wh)throw new IllegalArgumentException("Mỗi phiếu nộp tiền thuộc một kho");warehouse=wh;chosen.add(c);total+=((Number)c.get("amount")).longValue();}String note=string(b,"note",0,500);Long id=jdbc.queryForObject("INSERT INTO cash_handovers(driver_id,warehouse_id,amount,collection_ids,note) VALUES(?,?,?,?::jsonb,?) RETURNING id",Long.class,did,warehouse,total,encode(seen),note);for(var c:chosen)jdbc.update("INSERT INTO cash_handover_items(collection_id,handover_id) VALUES(?,?)",c.get("id"),id);return Map.of("id",id,"amount",total,"status","pending");});}
 @GetMapping("/api/payments/overview") public Map<String,Object> overview(@RequestParam(required=false) Integer warehouse,HttpServletRequest req){user(req,"dispatcher");String wh=warehouse==null?"":" WHERE o.warehouse_id=?";return Map.of("drivers",jdbc.queryForList("SELECT d.id,d.name,d.code,coalesce(sum(c.amount) FILTER(WHERE c.received_by='driver' AND c.method<>'external' AND coalesce(h.status,'')<>'approved' AND (r.id IS NULL OR r.paid_by<>'driver')),0) AS holding FROM drivers d LEFT JOIN payment_collections c ON c.driver_id=d.id LEFT JOIN orders o ON o.id=c.order_id LEFT JOIN cash_handover_items hi ON hi.collection_id=c.id LEFT JOIN cash_handovers h ON h.id=hi.handover_id LEFT JOIN payment_refunds r ON r.collection_id=c.id"+(warehouse==null?"":" WHERE d.warehouse_id=?")+" GROUP BY d.id ORDER BY d.code",warehouse==null?new Object[]{}:new Object[]{warehouse}),"handovers",jdbc.queryForList("SELECT h.*,d.name AS driver_name FROM cash_handovers h JOIN drivers d ON d.id=h.driver_id"+(warehouse==null?"":" WHERE h.warehouse_id=?")+" ORDER BY h.id DESC LIMIT 100",warehouse==null?new Object[]{}:new Object[]{warehouse}),"unpaid",jdbc.queryForList("SELECT o.id,o.code,o.stage,o.shipping_fee_vnd,p.payment_status,p.remittance_status FROM orders o JOIN order_payments p ON p.order_id=o.id"+wh+(wh.isEmpty()?" WHERE ":" AND ")+"p.payment_status IN ('unpaid','unverified') ORDER BY o.id DESC LIMIT 100",warehouse==null?new Object[]{}:new Object[]{warehouse}),"refundsDue",jdbc.queryForList("SELECT o.id,o.code,p.paid_amount AS amount,c.payer,c.driver_id,p.remittance_status FROM orders o JOIN payment_collections c ON c.order_id=o.id JOIN order_payments p ON p.order_id=o.id WHERE o.stage='returned' AND p.payment_status='paid'"+(warehouse==null?"":" AND o.warehouse_id=?")+" ORDER BY o.id DESC LIMIT 100",warehouse==null?new Object[]{}:new Object[]{warehouse}));}
 @PostMapping("/api/payments/handovers/{id}/{action}") @Transactional public Map<String,Object> review(@PathVariable long id,@PathVariable String action,@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req,"dispatcher");return once("review-handover:"+id+":"+action,b,((Number)u.get("id")).longValue(),()->{if(!Set.of("approve","reject").contains(action))throw new IllegalArgumentException("Thao tác không hợp lệ");var h=jdbc.queryForMap("SELECT * FROM cash_handovers WHERE id=? FOR UPDATE",id);if(!"pending".equals(h.get("status")))conflict("Phiếu nộp tiền đã được xử lý");String reason=string(b,"reason",action.equals("reject")?3:0,500);jdbc.update("UPDATE cash_handovers SET status=?,reviewed_by=?,reviewed_at=now(),review_note=? WHERE id=?",action.equals("approve")?"approved":"rejected",u.get("id"),reason,id);if(action.equals("reject"))jdbc.update("DELETE FROM cash_handover_items WHERE handover_id=?",id);jdbc.update("INSERT INTO driver_notifications(driver_id,source_key,type,title,message) VALUES(?,?,'cash_handover_reviewed',?,?)",h.get("driver_id"),"cash-handover:"+id,action.equals("approve")?"Đã xác nhận nhận tiền tài xế nộp":"Phiếu nộp tiền cần kiểm tra lại","Phiếu #"+id+" · "+h.get("amount")+" đ · "+reason);return Map.of("reviewed",true);});}
 @PostMapping("/api/payments/orders/{id}/refund") @Transactional public Map<String,Object> refund(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req,"dispatcher");return once("refund:"+id,b,((Number)u.get("id")).longValue(),()->{var c=jdbc.queryForMap("SELECT c.*,p.paid_amount AS effective_amount,o.stage,p.remittance_status FROM payment_collections c JOIN orders o ON o.id=c.order_id JOIN order_payments p ON p.order_id=o.id WHERE c.order_id=? FOR UPDATE OF c",id);if(!"returned".equals(c.get("stage")))conflict("Chỉ hoàn cước sau khi đã hoàn hàng về người gửi");if("pending_handover".equals(c.get("remittance_status")))conflict("Xử lý phiếu nộp tiền đang chờ trước khi hoàn cước");if(jdbc.queryForObject("SELECT count(*) FROM payment_refunds WHERE collection_id=?",Integer.class,c.get("id"))>0)conflict("Khoản cước đã được hoàn");String holder=("driver_holding".equals(c.get("remittance_status"))||"external".equals(c.get("remittance_status")))?"driver":"company",method=choice(b,"method","cash","transfer"),ref=string(b,"reference",method.equals("transfer")?3:0,120),reason=string(b,"reason",3,500);jdbc.update("INSERT INTO payment_refunds(collection_id,amount,paid_by,method,reference,reason,created_by) VALUES(?,?,?,?,?,?,?)",c.get("id"),c.get("effective_amount"),holder,method,ref,reason,u.get("id"));jdbc.update("INSERT INTO customer_tracking_events(order_id,type,reason) VALUES(?,'payment_refunded',?)",id,"Đã hoàn cước "+c.get("effective_amount")+" đ · "+reason);jdbc.update("INSERT INTO driver_notifications(driver_id,source_key,type,title,message) VALUES(?,?,'payment_refunded','Đã ghi nhận hoàn cước',?)",c.get("driver_id"),"payment-refund:"+id,"Đơn #"+id+" · "+c.get("effective_amount")+" đ");return Map.of("refunded",true,"amount",c.get("effective_amount"));});}
}
